solution.javascript:
function nombreDeRoutes(carte, depart, arrivee) {
  if (carte[depart] === undefined || carte[arrivee] === undefined) {
    return -1;
  }
  const distance = {};
  distance[depart] = 0;
  const file = [depart];
  for (let i = 0; i < file.length; i++) {
    const village = file[i];
    if (village === arrivee) {
      return distance[village];
    }
    for (const voisin of carte[village]) {
      if (distance[voisin] === undefined) {
        distance[voisin] = distance[village] + 1;
        file.push(voisin);
      }
    }
  }
  return -1;
}

