solution.javascript:
function trajetRapide(carte, depart, arrivee) {
  if (carte[depart] === undefined || carte[arrivee] === undefined) {
    return null;
  }
  // Durée minimale de chaque village jusqu'à l'arrivée (Dijkstra)
  const dist = {};
  dist[arrivee] = 0;
  const termines = new Set();
  while (true) {
    let u = null;
    for (const v of Object.keys(dist)) {
      if (termines.has(v)) continue;
      if (u === null || dist[v] < dist[u] || (dist[v] === dist[u] && v < u)) {
        u = v;
      }
    }
    if (u === null) break;
    termines.add(u);
    for (const v of Object.keys(carte[u])) {
      const d = dist[u] + carte[u][v];
      if (dist[v] === undefined || d < dist[v]) {
        dist[v] = d;
      }
    }
  }
  if (dist[depart] === undefined) {
    return null;
  }
  // On descend vers l'arrivée en prenant le plus petit nom à chaque pas
  const chemin = [depart];
  let courant = depart;
  while (courant !== arrivee) {
    let choix = null;
    for (const v of Object.keys(carte[courant]).sort()) {
      if (dist[v] !== undefined && carte[courant][v] + dist[v] === dist[courant]) {
        choix = v;
        break;
      }
    }
    chemin.push(choix);
    courant = choix;
  }
  return { duree: dist[depart], chemin: chemin };
}

solution.python:
def trajet_rapide(carte, depart, arrivee):
    if depart not in carte or arrivee not in carte:
        return None
    # Durée minimale de chaque village jusqu'à l'arrivée (Dijkstra)
    dist = {arrivee: 0}
    termines = set()
    while True:
        u = None
        for v in dist:
            if v in termines:
                continue
            if u is None or (dist[v], v) < (dist[u], u):
                u = v
        if u is None:
            break
        termines.add(u)
        for v in carte[u]:
            d = dist[u] + carte[u][v]
            if v not in dist or d < dist[v]:
                dist[v] = d
    if depart not in dist:
        return None
    # On descend vers l'arrivée en prenant le plus petit nom à chaque pas
    chemin = [depart]
    courant = depart
    while courant != arrivee:
        choix = None
        for v in sorted(carte[courant]):
            if v in dist and carte[courant][v] + dist[v] == dist[courant]:
                choix = v
                break
        chemin.append(choix)
        courant = choix
    return {"duree": dist[depart], "chemin": chemin}

